WITH flattened_attrs AS (SELECT id, service, log_ts, level, latency_ms, context, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text, context['version'] AS version, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier, SHIFTRIGHT(status_code, 2) AS status_code_high, CAST((status_code & 2) != 0 AS INT) AS flag_bit2 FROM app_logs WHERE level = 'INFO') SELECT DATE_TRUNC('DAY', log_ts) AS activity_day, service, SIZE(COLLECT_SET(service)) AS num_services, BIT_AND(latency_ms) AS latency_ms_bit_and, BIT_OR(latency_ms) AS latency_ms_bit_or, MIN(log_ts) AS first_seen FROM flattened_attrs GROUP BY activity_day, service;
